def foldtypes(x,n,t):
 if t=='disc':return foldn(x,n)
 if t=='phys':return foldphys(x,n)
 if t=='clip':return max(0,min(n-1,x))
 if t=='wrap':return x%n

def transform(s,pr,pc,n,ft,mode='both',presaxis=True):
 out=set()
 for r,c in s:
  if presaxis and c==pc:out.add((r,c));continue
  ps=[]
  cw=(pr+(c-pc),pc-(r-pr))
  ccw=(pr-(c-pc),pc+(r-pr))
  if mode=='both':ps=[cw,ccw]
  elif mode=='cw':ps=[cw]
  elif mode=='ccw':ps=[ccw]
  elif mode=='split': ps=[cw if c<pc else ccw]
  for rr,cc in ps:out.add((foldtypes(rr,n,ft),foldtypes(cc,n,ft)))
 return out
